function countEvenFromCards(digits: number[]): number {
  const seen = new Set<number>();
  const n = digits.length;
  for (let a = 0; a < n; a++) {
    if (digits[a] === 0) continue;
    for (let b = 0; b < n; b++) {
      if (b === a) continue;
      for (let c = 0; c < n; c++) {
        if (c === a || c === b || digits[c] % 2 !== 0) continue;
        seen.add(digits[a] * 100 + digits[b] * 10 + digits[c]);
      }
    }
  }
  return seen.size;
}

