function countEvenFromCards(digits: number[]): number {
  const cards = new Array(10).fill(0);
  for (const d of digits) cards[d]++;
  let count = 0;
  for (let x = 100; x < 1000; x += 2) {
    const need = new Array(10).fill(0);
    need[Math.floor(x / 100)]++;
    need[Math.floor(x / 10) % 10]++;
    need[x % 10]++;
    if (need.every((k, d) => k <= cards[d])) count++;
  }
  return count;
}

